            JavaScript

    function nextPermutation(N) {
    // If number of digits is 1 then just return "Not Possible"
    if (N.length === 1) {
        return "Not Possible";
    }

    // Start from the right most digit and find the first
    // digit that is smaller than the digit next to it.
    let i = N.length - 1;
    while (i > 0) {
        if (N[i] > N[i - 1]) {
            break;
        }
        i--;
    }

    // If i is 0 that means elements are in decreasing order
    // Therefore, no greater element possible
    if (i === 0) {
        return "Not Possible";
    }

    // Find the smallest digit on right side of (i-1)'th
    // digit that is greater than N[i-1]
    for (let j = N.length - 1; j >= i; j--) {
        if (N[i - 1] < N[j]) {
            // Swap the found smallest digit i.e. N[j]
            // with N[i-1]
            let chars = N.split('');
            let temp = chars[i - 1];
            chars[i - 1] = chars[j];
            chars[j] = temp;
            N = chars.join('');
            break;
        }
    }

    // Reverse the digits after (i-1) because the digits
    // after (i-1) are in decreasing order and thus we will
    // get the smallest element possible from these digits
    let chars = N.split('');
    reverse(chars, i);
    N = chars.join('');

    return N;
}

function reverse(arr, start) {
    let end = arr.length - 1;
    while (start < end) {
        let temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

